// Local personal-best replay. Visual only: never changes simulation or rewards.
let ghostEnabled=true;try{ghostEnabled=localStorage.getItem('starway-ghost-enabled')!=='false'}catch{}
let ghostReplay=null,ghostSamples=[],ghostKey='',ghostLastSample=-1,ghostRunLevel=-1;
function ghostMapKey(){let h=2166136261;const s=JSON.stringify(STORY_COURSES[level]);for(let i=0;i<s.length;i++)h=Math.imul(h^s.charCodeAt(i),16777619);return 'starway-ghost-v2-'+level+'-'+(h>>>0).toString(16)}
function syncGhostButton(){const b=$('ghostToggle');b.textContent='GHOST '+(ghostEnabled?'ON':'OFF');b.setAttribute('aria-pressed',String(ghostEnabled));b.title=tr('개인 최고기록 고스트 · 스토리 모드');}
$('ghostToggle').onclick=()=>{ghostEnabled=!ghostEnabled;try{localStorage.setItem('starway-ghost-enabled',String(ghostEnabled))}catch{}syncGhostButton()};syncGhostButton();
function validGhost(r){return r&&r.v===2&&r.completed===true&&Number.isFinite(r.best)&&r.best>0&&Number.isInteger(r.skin)&&r.skin>=0&&r.skin<skins.length&&Array.isArray(r.samples)&&r.samples.length>=2&&r.samples.length<=12002&&r.samples.every((s,i)=>Array.isArray(s)&&s.length===6&&s.every(Number.isFinite)&&s[0]>=0&&(!i||s[0]>r.samples[i-1][0]))&&Math.abs(r.samples.at(-1)[0]-r.best)<.02}
function captureGhost(force=false){if(mode!=='story'||editorTesting||level!==ghostRunLevel||!ghostKey)return;if(!force&&time-ghostLastSample<.099)return;if(ghostSamples.length>=12001)return;const s=[time,x,y,z,vy,grounded?1:0].map(n=>Math.round(n*1000)/1000);if(ghostSamples.length&&s[0]<=ghostSamples.at(-1)[0])return;ghostSamples.push(s);ghostLastSample=time;}
const ghostBeginRun=beginRun;beginRun=function(...args){const out=ghostBeginRun(...args);ghostReplay=null;ghostSamples=[];ghostLastSample=-1;ghostRunLevel=-1;ghostKey='';if(mode==='story'&&!editorTesting){ghostRunLevel=level;ghostKey=ghostMapKey();try{const r=JSON.parse(localStorage.getItem(ghostKey)||'null');if(validGhost(r))ghostReplay=r}catch{}captureGhost(true)}return out};
const ghostStep=step;step=function(dt){const recording=state==='play';const out=ghostStep(dt);if(recording&&state==='play')captureGhost();return out};
const ghostFinish=finish;finish=function(win,reason){const eligible=win&&state==='play'&&mode==='story'&&!editorTesting&&level===ghostRunLevel;const previous=eligible?ghostReplay?.best:null;if(eligible)captureGhost(true);const out=ghostFinish(win,reason);if(eligible&&state==='win'&&(!previous||time<previous)){const r={v:2,completed:true,best:time,skin:data.skin,samples:ghostSamples};if(validGhost(r))try{localStorage.setItem(ghostKey,JSON.stringify(r))}catch{ /* Preserve existing replay when storage is full. */ }}return out};result=finish;
function ghostAt(t){if(!ghostReplay||t<0||t>ghostReplay.best)return null;const a=ghostReplay.samples;let lo=0,hi=a.length-1;while(lo+1<hi){const mid=(lo+hi)>>1;if(a[mid][0]<=t)lo=mid;else hi=mid}const p=a[lo],q=a[hi],u=Math.max(0,Math.min(1,(t-p[0])/(q[0]-p[0])));return p.map((v,i)=>i===5?(u<.5?v:q[i]):v+(q[i]-v)*u)}
function drawPersonalGhost(){if(!ghostEnabled||mode!=='story'||editorTesting||!['play','ready','pause'].includes(state))return;const s=ghostAt(time);if(!s)return;const [,gx,gy,gz,gvy,gg]=s;if(gz<z-.6||gz>z+65)return;if(coinBlockedByBox(gz-.5,gx+roadCenterLane(),gy+.25))return;const p=proj(gx,gz,gy+.15),anchor=proj(gx,gz,.15),ahead=proj(gx,gz+1.5,.15),shear=(ahead[0]-anchor[0])/(ahead[1]-anchor[1]),scale=p[2]/proj(x,z,.15)[2],size=flightShipSize(ghostReplay.skin,p[2]);if(!Number.isFinite(size)||size<1)return;ctx.save();try{ctx.globalAlpha=.32;ctx.translate(p[0],p[1]);renderFlightShip(ctx,ghostReplay.skin,time,size,{heading:0,shear:Number.isFinite(shear)?Math.max(-1.25,Math.min(1.25,shear)):0,foreshortening:.54+(gg?0:Math.max(-.14,Math.min(.14,gvy*.018))),thrust:.25})}finally{ctx.restore()}}
const ghostDrawShip=drawShipAndEffects;drawShipAndEffects=function(...args){drawPersonalGhost();return ghostDrawShip(...args)};
